import ch.jalu.configme.exception.ConfigMeException;
import ch.jalu.configme.properties.Property;
import org.junit.Test;

import java.util.List;
import java.util.Map;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class PropertyListBuilderUnitTest {

    @Test(expected = ConfigMeException.class)
    public void addNullPropertyTest() {
        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(null);
    }

    @Test
    public void addMultiplePropertiesTest() {
		Property<?> mockProperty1 = mock(Property.class);
        Property<?> mockProperty2 = mock(Property.class);
        Property<?> mockProperty3 = mock(Property.class);

        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(mockProperty1);
        builder.add(mockProperty2);
        builder.add(mockProperty3);

        List<Property<?>> result = builder.create();

        assertEquals(3, result.size());
        assertTrue(result.contains(mockProperty1));
        assertTrue(result.contains(mockProperty2));
        assertTrue(result.contains(mockProperty3));
    }

	@Test
	public void createAfterAddingPropertyTest() {
		Property<?> mockProperty = mock(Property.class);

		PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(mockProperty);

        List<Property<?>> result = builder.create();
        assertTrue(result.contains(mockProperty));
		assertEquals(1, result.size());
	}

	@Test
	public void createEmptyListWhenNoPropertyAddedTest() {
		PropertyListBuilder builder = new PropertyListBuilder();

        List<Property<?>> result = builder.create();
        assertTrue(result.isEmpty());
	}

    @Test
    public void getRootEntriesAfterAddingPropertiesTest() {
		Property<?> mockProperty1 = mock(Property.class);
        when(mockProperty1.getPath()).thenReturn("prop1");
        Property<?> mockProperty2 = mock(Property.class);
        when(mockProperty2.getPath()).thenReturn("prop2");
        Property<?> mockProperty3 = mock(Property.class);
        when(mockProperty3.getPath()).thenReturn("prop3");

		PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(mockProperty1);
        builder.add(mockProperty2);
        builder.add(mockProperty3);

        Map<String, Object> result = builder.getRootEntries();

        assertEquals(3, result.size());
        assertTrue(result.containsKey("prop1"));
        assertTrue(result.containsKey("prop2"));
        assertTrue(result.containsKey("prop3"));
    }

    @Test
    public void getRootEntriesReturnsNewMapInstanceTest() {
		Property<?> mockProperty = mock(Property.class);
        when(mockProperty.getPath()).thenReturn("prop");

		PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(mockProperty);

        Map<String, Object> firstResult = builder.getRootEntries();
        Map<String, Object> secondResult = builder.getRootEntries();

        assertNotSame(firstResult, secondResult);
        assertEquals(firstResult, secondResult);
    }

    @Test
    public void getRootEntriesReturnsEmptyMapIfNoPropertiesTest() {
        PropertyListBuilder builder = new PropertyListBuilder();

        Map<String, Object> result = builder.getRootEntries();

        assertTrue(result.isEmpty());
    }
}
